<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title><?= html_escape($survey->title) ?></title><style>body{margin:0;background:#f0ebf8;font:15px Arial;color:#202124}.wrap{max-width:720px;margin:28px auto}.card{background:#fff;margin:12px 0;padding:25px;border-radius:8px;border:1px solid #dadce0}.hero{border-top:10px solid #673ab7}.title{font-size:31px;margin:0 0 12px}.q{font-size:16px;margin:0 0 18px}.required{color:#d93025}input[type=text],textarea,select{display:block;width:100%;box-sizing:border-box;border:0;border-bottom:1px solid #777;padding:10px 2px;font-size:15px;background:white}textarea{border:1px solid #ddd;border-radius:4px}.choice{display:block;margin:10px 0}button{background:#673ab7;color:#fff;border:0;border-radius:4px;padding:11px 25px;font-weight:bold;cursor:pointer}.error{color:#d93025;background:#fce8e6;padding:12px;border-radius:5px}</style></head><body><main class="wrap"><section class="card hero"><h1 class="title"><?= html_escape($survey->title) ?></h1><p><?= nl2br(html_escape($survey->description)) ?></p><p class="required">* Wajib diisi</p></section><?php if (validation_errors()): ?><div class="error"><?= validation_errors() ?></div><?php endif; ?><?= form_open('survey/submit') ?><?php foreach ($questions as $q): $options = array_filter(array_map('trim', explode("\n", $q->options))); ?><section class="card"><p class="q"><?= html_escape($q->question_text) ?> <?= $q->is_required ? '<span class="required">*</span>' : '' ?></p><?php if ($q->question_type === 'text'): ?><input type="text" name="answer[<?= $q->id ?>]" value="<?= html_escape(set_value('answer['.$q->id.']')) ?>"><?php elseif ($q->question_type === 'textarea'): ?><textarea name="answer[<?= $q->id ?>]" rows="4"><?= html_escape(set_value('answer['.$q->id.']')) ?></textarea><?php elseif ($q->question_type === 'select'): ?><select name="answer[<?= $q->id ?>]"><option value="">Pilih jawaban</option><?php foreach($options as $o): ?><option value="<?= html_escape($o) ?>"><?= html_escape($o) ?></option><?php endforeach; ?></select><?php else: foreach($options as $o): ?><label class="choice"><input type="<?= $q->question_type === 'checkbox' ? 'checkbox' : 'radio' ?>" name="answer[<?= $q->id ?>]<?= $q->question_type === 'checkbox' ? '[]' : '' ?>" value="<?= html_escape($o) ?>"> <?= html_escape($o) ?></label><?php endforeach; endif; ?></section><?php endforeach; ?><button type="submit">Kirim</button><?= form_close() ?></main></body></html>
